#include "resident/checkpoint/checkpoint_decode_lifecycle.hpp"
#include "task_exact_execution.hpp"
#include "task_dynamic_projection.hpp"
#include "resident/model/commitment_ref_codec.hpp"
namespace hanmo::resident {namespace {
template<class A>Status source(A&a,SourceRef&v){a.field("domain",v.domain);a.field("kind",v.kind);return a.field("id",v.id);}
template<class A>Status catalog(A&a,CatalogIdentity&v){a.field("content_id",v.content_id);a.field("content_version",v.content_version);a.field("content_digest",v.content_digest);a.field("ruleset_id",v.ruleset_id);a.field("schema_sha256",v.schema_sha256);a.optional("pack_set_digest",v.pack_set_digest,[](auto&c,auto&x){return c.field("value",x);});a.sequence("module_versions",v.module_versions,[](auto&c,auto&x){c.field("module",x.first);return c.field("version",x.second);});return a.field("artifact_sha256",v.artifact_sha256);}
template<class A>Status context(A&a,InteractionContext&v){a.field("place_id",v.place_id);a.field("provider_actor_id",v.provider_actor_id);a.field("role_id",v.role_id);a.optional("kind",v.kind,[](auto&c,auto&x){return c.field("value",x);});a.optional("encounter_id",v.encounter_id,[](auto&c,auto&x){return c.field("value",x);});a.optional("input_error",v.input_error,[](auto&c,auto&x){return c.field("value",x);});return dynamic_codec::strings(a,"field_order",v.field_order);}
template<class A>Status params(A&a,TaskAction&v){a.field("offer_id",v.offer_id);a.field("task_id",v.task_id);a.object("context",[&](auto&c){return context(c,v.context);});a.optional("reward",v.reward,[](auto&c,auto&x){return c.field("value",x);});a.optional("source_kind",v.source_kind,[](auto&c,auto&x){return c.field("value",x);});a.optional("delivery_quantity",v.delivery_quantity,[](auto&c,auto&x){return c.field("value",x);});a.field("restitution",v.restitution);return dynamic_codec::strings(a,"field_order",v.field_order);}
template<class A>Status effect(A&a,TaskEffect&v){a.field("success",v.success);a.optional("task_id",v.task_id,[](auto&c,auto&x){return c.field("value",x);});a.optional("code",v.code,[](auto&c,auto&x){return c.field("value",x);});a.optional("on_unavailable",v.on_unavailable,[](auto&c,auto&x){return c.field("value",x);});a.optional("retry",v.retry,[](auto&c,auto&x){return c.field("value",x);});return dynamic_codec::strings(a,"field_order",v.field_order);}
template<class A>Status start_fields(A&c,TaskExactStartSource&v){c.field("id",v.id);c.field("action_id",v.action_id);c.field("action_kind",v.action_kind);c.field("actor_id",v.actor_id);dynamic_codec::strings(c,"participants",v.participants);c.object("accepted_action",[&](auto&x){return params(x,v.accepted_action);});c.field("required_half_days",v.required_half_days);c.object("started_at",[&](auto&x){return dynamic_codec::exact_moment(x,v.started_at);});c.object("catalog_identity",[&](auto&x){return catalog(x,v.catalog_identity);});c.object("terms_revision",[&](auto&x){return commitment_codec::terms(x,v.terms_revision);});return c.sequence("actual_start_sources",v.actual_start_sources,[](auto&x,auto&ref){return source(x,ref);});}
template<class A>Status terminal_fields(A&c,TaskExactTerminalSource&v,Integer selected){if(selected==1&&!c.reading()&&v.participant_death)return c.reject("UnexpectedTaskExactDeathSource");c.field("id",v.id);c.field("start_source_id",v.start_source_id);c.field("action_id",v.action_id);c.object("finished_at",[&](auto&x){return dynamic_codec::exact_moment(x,v.finished_at);});c.object("effect",[&](auto&x){return effect(x,v.effect);});c.field("task_status_after",v.task_status_after);c.field("settlement_id_after",v.settlement_id_after);c.sequence("actual_result_sources",v.actual_result_sources,[](auto&x,auto&ref){return source(x,ref);});dynamic_codec::enumeration(c,"disposition",v.disposition,3);if(selected==2)c.optional("participant_death",v.participant_death,[](auto&x,auto&cause){x.object("death_ref",[&](auto&y){y.field("domain",cause.death_ref.domain);y.field("kind",cause.death_ref.kind);return y.field("id",cause.death_ref.id);});return dynamic_codec::enumeration(x,"role",cause.role,1);});return c.status();}
template<class A>Status fields(A&a,TaskExactExecutionState&s,Integer selected){if(!task_exact_execution_version(selected))return a.reject("UnsupportedTaskExactExecutionSchema");a.field("version",s.version);if(s.version!=selected)return a.reject("TaskExactExecutionSelectionMismatch");dynamic_codec::table(a,"starts",s.starts,[](auto&c,auto&v){return start_fields(c,v);});dynamic_codec::table(a,"terminals",s.terminals,[selected](auto&c,auto&v){return terminal_fields(c,v,selected);});return a.status();}
}
Outcome<TaskExactExecutionState> decode_task_exact_execution(const BoundaryValue&input,Integer selected){dynamic_codec::JsonArchive a(input);auto ready=a.prepare_default_values<TaskExactExecutionState>();if(!ready.ok)return {false,{},ready.error};TaskExactExecutionState value;value.version=selected;auto s=fields(a,value,selected);if(s.ok)s=a.finish();return s.ok?Outcome<TaskExactExecutionState>{true,std::move(value),{}}:Outcome<TaskExactExecutionState>{false,{},s.error};}
Outcome<TaskExactExecutionState> decode_task_exact_execution(const BoundaryValue&input){return decode_task_exact_execution(input,1);}
Outcome<BoundaryValue> encode_task_exact_execution(const TaskExactExecutionState&value,Integer selected){return dynamic_projection::encode(value,[selected](auto&a,auto&v){return fields(a,v,selected);});}
Outcome<BoundaryValue> encode_task_exact_execution(const TaskExactExecutionState&value){return encode_task_exact_execution(value,1);}
Status visit_task_exact_execution_checkpoint(CodecVisitor&a,TaskExactExecutionState&value,Integer selected){return fields(a,value,selected);}
Status visit_task_exact_execution_checkpoint(CodecVisitor&a,TaskExactExecutionState&value){return visit_task_exact_execution_checkpoint(a,value,1);}
Status emit_task_exact_execution_projection(ProjectionWriter&w,std::string_view key,const TaskExactExecutionState&value,Integer selected){return dynamic_projection::emit(w,key,value,[selected](auto&a,auto&v){return fields(a,v,selected);});}
Status emit_task_exact_execution_projection(ProjectionWriter&w,std::string_view key,const TaskExactExecutionState&value){return emit_task_exact_execution_projection(w,key,value,1);}
Outcome<bool> emit_task_exact_original_fact_payload_fields(ProjectionWriter&w,const CommonStore&common,const TaskState&tasks,const FactRecord&header,Integer selected){
 auto schema=read_task_exact_original_fact_schema(common,tasks,header,selected);if(!schema.ok)return {false,false,std::move(schema.error)};
 if(!schema.value)return {true,false,{}};
 DynamicProjectionArchive archive(w);Status status;
 if(header.kind=="task_action_started")status=start_fields(archive,const_cast<TaskExactStartSource&>(*tasks.exact_execution->starts.find(header.id)));
 else status=terminal_fields(archive,const_cast<TaskExactTerminalSource&>(*tasks.exact_execution->terminals.find(header.id)),selected);
 return status.ok?Outcome<bool>{true,true,{}}:Outcome<bool>{false,false,std::move(status.error)};
}

}
